import json, glob
for day in ['25','26']:
    print(f"===== 2026-03-{day} =====")
    for fp in glob.glob(f'articles/2026/03/{day}/*.jsonl'):
        with open(fp) as f:
            for line in f:
                try:
                    a = json.loads(line)
                    print("-", a.get('title','')[:130], f"[{a.get('source','')}]")
                except: pass
EOF

